{
  "story": "Text is broken down into smaller pieces called tokens. Algorithms map these pieces to numbers before processing begins.",
  "aha": {
    "stateId": "s3",
    "observation": "Subwords and characters handle unseen vocabulary by splitting words into known units."
  },
  "layout": {
    "preset": "card",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "pic",
      "kind": "fixed-picture",
      "bind": {
        "active": "inputs.stepIndex",
        "regions": "variant.regions",
        "values": "variant.states.active"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "variant.states.why",
        "target": "variant.states.calloutRegion",
        "text": "variant.states.sentence"
      }
    },
    {
      "id": "readout",
      "kind": "value-readout",
      "bind": {
        "values": "variant.states.readouts"
      }
    },
    {
      "id": "prog",
      "kind": "progress",
      "bind": {
        "completedBefore": "inputs.stepIndex"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Step",
      "options": [
        "Raw Input",
        "Normalization",
        "Pre-tokenization",
        "Model Split",
        "ID Mapping"
      ]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset",
      "options": []
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Tokenization Pipeline",
        "regions": [
          {
            "id": "r1",
            "label": "Raw Text",
            "kind": "box",
            "values": ["Language Models love data."]
          },
          {
            "id": "r2",
            "label": "Normalized Text",
            "kind": "box",
            "values": ["language models love data."]
          },
          {
            "id": "r3",
            "label": "Split Words",
            "kind": "box",
            "values": ["language", "models", "love", "data."]
          },
          {
            "id": "r4",
            "label": "Subword Tokens",
            "kind": "box",
            "values": ["language", "models", "love", "data", "."]
          },
          {
            "id": "r5",
            "label": "Token IDs",
            "kind": "box",
            "values": ["2769", "3905", "1829", "1258", "13"]
          }
        ],
        "states": [
          {
            "id": "s0",
            "label": "Input",
            "short": "Raw",
            "sentence": "Raw text enters the tokenizer pipeline directly from the user.",
            "why": "Establishes the starting text string.",
            "active": ["r1"],
            "calloutRegion": "r1",
            "readouts": [
              {
                "id": "ro1",
                "label": "Length",
                "value": "26 chars"
              }
            ]
          },
          {
            "id": "s1",
            "label": "Normalize",
            "short": "Norm",
            "sentence": "Text is stripped of extra whitespace and converted to lower case.",
            "why": "Ensures uniform text formatting.",
            "active": ["r2"],
            "calloutRegion": "r2",
            "readouts": [
              {
                "id": "ro2",
                "label": "Case",
                "value": "Lower"
              }
            ]
          },
          {
            "id": "s2",
            "label": "Pre-tokenize",
            "short": "Split",
            "sentence": "Spaces and punctuation split the string into initial word chunks.",
            "why": "Isolates individual words.",
            "active": ["r3"],
            "calloutRegion": "r3",
            "readouts": [
              {
                "id": "ro3",
                "label": "Words",
                "value": "4"
              }
            ]
          },
          {
            "id": "s3",
            "label": "Model Split",
            "short": "Subword",
            "sentence": "BPE or WordPiece algorithms divide complex words into subwords.",
            "why": "Prevents out-of-vocabulary errors.",
            "active": ["r4"],
            "calloutRegion": "r4",
            "readouts": [
              {
                "id": "ro4",
                "label": "Tokens",
                "value": "5"
              }
            ]
          },
          {
            "id": "s4",
            "label": "Map IDs",
            "short": "IDs",
            "sentence": "Each token string is converted to a unique integer index.",
            "why": "Prepares numerical inputs for the neural network.",
            "active": ["r5"],
            "calloutRegion": "r5",
            "readouts": [
              {
                "id": "ro5",
                "label": "Vocab Size",
                "value": "50257"
              }
            ]
          }
        ]
      }
    ]
  }
}
